                case 0:
                    bw(b, "alt -> "_s, u32(i->Out), ", "_s, u32(i->Arg));
                    break;
                case 1:
                    bw(b, "altmatch -> "_s, u32(i->Out), ", "_s, u32(i->Arg));
                    break;
                case 2:
                    bw(b, "cap "_s, u32(i->Arg), " -> "_s, u32(i->Out));
                    break;
                case 3:
                    bw(b, "empty "_s, u32(i->Arg), " -> "_s, u32(i->Out));
                    break;
                case 4:
                    bw(b, "match"_s);
                    break;
                case 5:
                    bw(b, "fail"_s);
                    break;
                case 6:
                    bw(b, "nop -> "_s, u32(i->Out));
                    break;
                case 7:
                    if(i->Rune == nullptr)
                    {
                        // shouldn't happen
                        bw(b, "rune <nil>"_s);
                    }
                    bw(b, "rune "_s, strconv::QuoteToASCII(gocpp::string(i->Rune)));
                    if(Flags(i->Arg) & FoldCase != 0)
                    {
                        bw(b, "/i"_s);
                    }
                    bw(b, " -> "_s, u32(i->Out));
                    break;
                case 8:
                    bw(b, "rune1 "_s, strconv::QuoteToASCII(gocpp::string(i->Rune)), " -> "_s, u32(i->Out));
                    break;
                case 9:
                    bw(b, "any -> "_s, u32(i->Out));
                    break;
                case 10:
                    bw(b, "anynotnl -> "_s, u32(i->Out));
                    break;
